<?php
require __DIR__.'/config.php'; require_role(['admin']);
$students=read_json('students');$invoices=read_json('invoices');$payments=read_json('payments');$receipts=read_json('receipts');
function student_name8($students,$id){foreach($students as $s)if((int)$s['id']===(int)$id)return $s['name']??'Unknown';return 'Unknown';}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
if($action==='invoice'){$sid=(int)$_POST['student_id'];$amount=(float)$_POST['amount'];$invoices[]=['id'=>next_id($invoices),'student_id'=>$sid,'invoice_no'=>'RF-INV-'.date('Y').'-'.str_pad((string)(count($invoices)+1),5,'0',STR_PAD_LEFT),'description'=>trim($_POST['description']),'amount'=>$amount,'due_date'=>$_POST['due_date'],'status'=>'Unpaid','created_at'=>date('c')];write_json('invoices',$invoices);log_action('create','invoice',$sid);flash('Invoice created.');}
if($action==='payment'){$sid=(int)$_POST['student_id'];$amount=(float)$_POST['amount'];$rid=next_id($receipts);$receipt=['id'=>$rid,'receipt_no'=>'RF-RCP-'.date('Y').'-'.str_pad((string)($rid),5,'0',STR_PAD_LEFT),'student_id'=>$sid,'amount'=>$amount,'method'=>trim($_POST['method']),'reference'=>trim($_POST['reference']),'date'=>date('Y-m-d'),'created_at'=>date('c')];$payments[]=$receipt;$receipts[]=$receipt;write_json('payments',$payments);write_json('receipts',$receipts);log_action('create','payment',$sid);flash('Payment recorded. Receipt created: '.$receipt['receipt_no']);}
redirect('finance.php');}
$balances=[];$totalInvoiced=0;$totalPaid=0;
foreach($students as $st){$sid=(int)$st['id'];$inv=array_sum(array_map(fn($x)=>(int)$x['student_id']===$sid?(float)$x['amount']:0,$invoices));$pay=array_sum(array_map(fn($x)=>(int)$x['student_id']===$sid?(float)$x['amount']:0,$payments));$balances[]=['id'=>$sid,'name'=>$st['name']??'','invoiced'=>$inv,'paid'=>$pay,'balance'=>$inv-$pay];$totalInvoiced+=$inv;$totalPaid+=$pay;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finance — Ridgefield</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1200px;margin:auto;padding:28px}.stats,.forms{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid #dde3dd;border-radius:14px;padding:20px}.metric{font-size:30px;font-weight:700}.table{width:100%;border-collapse:collapse;margin-top:20px}.table td,.table th{padding:9px;border-bottom:1px solid #ddd;text-align:left}.forms{grid-template-columns:1fr 1fr}.formbox{padding:20px;border:1px solid #dde3dd;border-radius:14px}input,select{width:100%;box-sizing:border-box;margin:5px 0 12px}@media(max-width:800px){.stats,.forms{grid-template-columns:1fr}.table{display:block;overflow:auto}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="school.php">← School Management</a></p><h1>Fees & Finance</h1><div class="stats"><div class="card"><div class="metric">R <?=number_format($totalInvoiced,2)?></div><p>Total invoiced</p></div><div class="card"><div class="metric">R <?=number_format($totalPaid,2)?></div><p>Total payments</p></div><div class="card"><div class="metric">R <?=number_format($totalInvoiced-$totalPaid,2)?></div><p>Outstanding</p></div></div>
<div class="forms" style="margin-top:18px"><div class="formbox"><h2>Create invoice</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="invoice"><label>Student<select name="student_id" required><?php foreach($students as $st):?><option value="<?=$st['id']?>"><?=h($st['name'])?></option><?php endforeach;?></select></label><label>Description<input name="description" required placeholder="Term tuition"></label><label>Amount<input type="number" step="0.01" name="amount" required></label><label>Due date<input type="date" name="due_date" required></label><button>Create invoice</button></form></div>
<div class="formbox"><h2>Record payment</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="payment"><label>Student<select name="student_id" required><?php foreach($students as $st):?><option value="<?=$st['id']?>"><?=h($st['name'])?></option><?php endforeach;?></select></label><label>Amount<input type="number" step="0.01" name="amount" required></label><label>Method<select name="method"><option>Cash</option><option>Bank Transfer</option><option>Card</option><option>Other</option></select></label><label>Reference<input name="reference"></label><button>Record payment</button></form></div></div>
<div class="card" style="margin-top:18px"><h2>Student balances</h2><table class="table"><tr><th>Student</th><th>Invoiced</th><th>Paid</th><th>Balance</th><th>Statement</th></tr><?php foreach($balances as $b):?><tr><td><?=h($b['name'])?></td><td>R <?=number_format($b['invoiced'],2)?></td><td>R <?=number_format($b['paid'],2)?></td><td><strong>R <?=number_format($b['balance'],2)?></strong></td><td><a href="statement.php?student_id=<?=$b['id']?>">View</a></td></tr><?php endforeach;?></table></div></div><script src="assets/dynamic-site.js"></script>
</body></html>